INSERT OR IGNORE INTO notices (id, title, content, tag, pinned, published, date, created_at, updated_at) VALUES ('ann-006', '공식 홈페이지 리뉴얼 오픈', '함대 정체성과 방향성을 명확히 보여주기 위한 공식 홈페이지가 새롭게 개편되었습니다. 임원진 소개, 연혁, 무역허브, 운영정책 등 주요 정보를 확인하실 수 있습니다.', '공지', '1', '1', '2026.05.15', '2026-05-25T06:59:04.247Z', '2026-05-25T06:59:04.247Z');
INSERT OR IGNORE INTO notices (id, title, content, tag, pinned, published, date, created_at, updated_at) VALUES ('ann-005', 'VOLT 운영정책 정식 시행', '함대 운영 전반에 대한 운영정책이 오늘부터 정식 적용됩니다. 닉네임 규정, 위반 항목, 누적 경고 제재 등 전문을 반드시 숙지해 주시기 바랍니다.', '정책', '0', '1', '2026.05.15', '2026-05-25T06:59:04.247Z', '2026-05-25T06:59:04.247Z');
INSERT OR IGNORE INTO notices (id, title, content, tag, pinned, published, date, created_at, updated_at) VALUES ('ann-004', 'VOLT × MJO 합동 교류 작전', 'MJO 함대와의 친선 협력 강화를 위한 합동 교류 작전이 진행되었습니다. 폴라리스 운용 및 매복 미션을 통해 양 함대 간 신뢰를 쌓는 계기가 되었습니다.', '작전', '0', '1', '2026.02.22', '2026-05-25T06:59:04.247Z', '2026-05-25T06:59:04.247Z');
INSERT OR IGNORE INTO notices (id, title, content, tag, pinned, published, date, created_at, updated_at) VALUES ('ann-003', 'VOLT AI 봇 공식 오픈', 'Google Gemini 기반의 VOLT AI가 디스코드에 공식 오픈되었습니다. 함선 데이터베이스 검색, AI 정밀 분석 등 다양한 기능을 디스코드에서 이용하실 수 있습니다.', '시스템', '0', '1', '2026.02.02', '2026-05-25T06:59:04.247Z', '2026-05-25T06:59:04.247Z');
INSERT OR IGNORE INTO notices (id, title, content, tag, pinned, published, date, created_at, updated_at) VALUES ('ann-002', 'VOLT-무역허브 공식 개설', '함대 전용 통합 교역 시스템 VOLT-무역허브가 공식 개설되었습니다. 인게임 아이템 거래 및 단기 임무 모집을 디스코드 내 전용 채널에서 진행할 수 있습니다.', '시스템', '0', '1', '2025.11.24', '2026-05-25T06:59:04.247Z', '2026-05-25T06:59:04.247Z');
INSERT OR IGNORE INTO notices (id, title, content, tag, pinned, published, date, created_at, updated_at) VALUES ('ann-001', 'Lazarus Complex 레이드 완료', '하반기 첫 공식 단체 작전이 성공적으로 완료되었습니다. Pyro 시스템 Lazarus Complex에서 10명 내외 함대원이 공격팀·방어팀으로 나뉘어 협동 임무를 수행하였습니다.', '작전', '0', '1', '2025.08.02', '2026-05-25T06:59:04.247Z', '2026-05-25T06:59:04.247Z');
INSERT OR IGNORE INTO events (id, title, description, type, status, date_label, event_date, published, created_at, updated_at) VALUES ('cal-001', 'TSG 미션 (4.8 업데이트 후)', '4.8 업데이트 이후 진행 예정. 우주팀(함대 기동·제공권 확보)과 스테이션 진입팀(FPS 교전)으로 나뉘어 수행.', '작전', '예정', '2026년 8월 예정', '', '1', '2026-05-25T06:59:04.247Z', '2026-05-25T06:59:04.247Z');
INSERT OR IGNORE INTO events (id, title, description, type, status, date_label, event_date, published, created_at, updated_at) VALUES ('cal-002', '분기 정기 이벤트', '함대원 전원이 참여하는 분기별 공식 이벤트. 세부 일정은 디스코드 공지 채널에서 확인.', '이벤트', '예정', '2026년 3분기', '', '1', '2026-05-25T06:59:04.247Z', '2026-05-25T06:59:04.247Z');
INSERT OR IGNORE INTO events (id, title, description, type, status, date_label, event_date, published, created_at, updated_at) VALUES ('cal-003', '유저 거래소 프로젝트 재개', '버그 수정 및 시장 경쟁력 확보 후 샤타곤 유저 거래소 프로젝트 재개 예정.', '프로젝트', '대기', '일정 미정', '', '1', '2026-05-25T06:59:04.247Z', '2026-05-25T06:59:04.247Z');
INSERT OR IGNORE INTO events (id, title, description, type, status, date_label, event_date, published, created_at, updated_at) VALUES ('cal-004', '세금 제도 도입', '스테이션·전초기지·함대 복지 운영을 위한 세금 제도 도입 예정. 정식오픈 초기 세율 높게 책정 후 안정화 이후 재조정.', '정책', '계획', '1.0 출시 후', '', '1', '2026-05-25T06:59:04.247Z', '2026-05-25T06:59:04.247Z');
